package main

import "net/http"

func (a *App) adminWebRoutes() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = w.Write([]byte(adminPage))
	})
}

const adminPage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Happy Friday 企业管理</title><style>body{font:14px system-ui,sans-serif;color:#172033;margin:0;background:#f6f8fb}main{max-width:920px;margin:32px auto;padding:0 20px}section{background:#fff;border:1px solid #dce2ea;padding:20px;margin:16px 0;border-radius:6px}input,select,button{font:inherit;padding:8px;margin:4px}input{min-width:180px;border:1px solid #b8c3d1;border-radius:4px}button{border:0;border-radius:4px;background:#075ec9;color:#fff;cursor:pointer}pre{white-space:pre-wrap;overflow:auto;background:#eef2f7;padding:12px;border-radius:4px}</style></head><body><main><h1>企业管理</h1><section><h2>管理员登录</h2><form id="login"><input name="email" type="email" placeholder="邮箱" required><input name="password" type="password" placeholder="密码" required><button>登录</button></form><p id="identity">未登录</p></section><section><h2>成员</h2><form id="member"><input name="email" type="email" placeholder="员工邮箱" required><input name="displayName" placeholder="姓名" required><input name="password" type="password" placeholder="初始密码（至少 12 位）" required><select name="role"><option value="member">成员</option><option value="org_admin">管理员</option></select><button>创建成员</button></form><button onclick="load('/api/v1/admin/members')">刷新成员列表</button><pre id="members"></pre></section><section><h2>共享模型</h2><form id="model"><input name="provider" placeholder="厂商标识" required><input name="displayName" placeholder="显示名称" required><input name="baseUrl" placeholder="API 地址" required><input name="modelName" placeholder="模型名" required><input name="apiKey" type="password" placeholder="API Key" required><button>新增模型</button></form><button onclick="load('/api/v1/admin/model-configs')">刷新模型列表</button><pre id="models"></pre></section><p>API Key 仅在创建时提交，后台列表只显示掩码。员工客户端将从受保护的模型配置接口获取已启用模型。</p></main><script>let token=sessionStorage.token||'';const out=(id,v)=>document.getElementById(id).textContent=JSON.stringify(v,null,2);function headers(){return {'Content-Type':'application/json','Authorization':'Bearer '+token}}async function request(url,method,body){const r=await fetch(url,{method,headers:headers(),body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'请求失败');return d.data}async function load(url){try{const d=await request(url,'GET');out(url.includes('members')?'members':'models',d)}catch(e){alert(e.message)}}document.getElementById('login').onsubmit=async e=>{e.preventDefault();try{const d=await request('/api/v1/auth/login','POST',Object.fromEntries(new FormData(e.target)));token=d.accessToken;sessionStorage.token=token;const me=await request('/api/v1/me','GET');document.getElementById('identity').textContent=me.displayName+'（'+me.role+'）';load('/api/v1/admin/members');load('/api/v1/admin/model-configs')}catch(x){alert(x.message)}};document.getElementById('member').onsubmit=async e=>{e.preventDefault();try{await request('/api/v1/admin/members','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();load('/api/v1/admin/members')}catch(x){alert(x.message)}};document.getElementById('model').onsubmit=async e=>{e.preventDefault();try{await request('/api/v1/admin/model-configs','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();load('/api/v1/admin/model-configs')}catch(x){alert(x.message)}};if(token){request('/api/v1/me','GET').then(m=>document.getElementById('identity').textContent=m.displayName+'（'+m.role+'）').catch(()=>{sessionStorage.removeItem('token');token=''})}</script></body></html>`
